from reportlab.platypus import Paragraph, Spacer, PageBreak
from manual_screens import CaptureCard

def users_pages(out, s):
    title = 'Gestión de usuarios: listado y navegación'
    intro = 'Accede a Configuración del sistema y selecciona Usuarios. El panel Usuarios del sistema reúne las cuentas de acceso y permite consultar su identificación, rol, estado y última conexión. Esta es la pantalla de partida para administrar los usuarios de KiwiKERP.'
    parts = [
        ('Qué muestra cada columna', 'Código identifica la cuenta; Usuario muestra el nombre y su imagen o iniciales. Rol indica el perfil mostrado por el sistema. Estado permite distinguir si la cuenta está activa. Última conexión muestra la fecha y hora registradas para el último acceso; no indica por sí sola que el usuario siga conectado.'),
        ('Dos perfiles en el listado', 'La captura muestra dos cuentas: una con rol Administrador y otra con rol Usuario. Ambas aparecen en estado ACTIVO y tienen su propia última conexión. El rol y el estado son datos distintos: estar activo no significa disponer de permisos de administrador. El total del listado es de dos registros; los permisos se explicarán en el apartado de seguridad.'),
        ('Buscar, ordenar y recorrer el listado', 'Utiliza Buscar registros para localizar usuarios. Los encabezados Código, Usuario y Rol muestran controles de ordenación. En la parte inferior aparecen el total y los controles de paginación, con selección de página, navegación y tamaño de página.'),
        ('Crear una cuenta', 'Pulsa Nuevo usuario, en la parte superior derecha, para abrir el formulario de alta. El procedimiento de creación y sus campos se explican en las siguientes páginas.'),
        ('Dos menús diferentes', 'El menú de tres puntos junto al buscador corresponde al listado. El menú de tres puntos de cada fila, en Acciones, corresponde a ese usuario. Antes de operar, comprueba el código y el nombre de la fila elegida.')
    ]
    opening = 'Antes de crear cuentas o asignar permisos, conviene distinguir los dos perfiles principales de este recorrido: Administrador y Usuario. El perfil determina el alcance del acceso; el estado activo indica si la cuenta está habilitada.'
    result = [Paragraph('Tipos de usuario y responsabilidades',s['h2']),Paragraph(opening,s['text'])]
    md = ['### Tipos de usuario y responsabilidades',opening]
    for h,t in [
        ('Administrador: gestionar la solución', 'Es el perfil encargado de administrar KiwiKERP y su configuración. Dispone de acceso general a los módulos, secciones y permisos contemplados por el sistema de seguridad, sin tener que habilitarlos individualmente. La cuenta creada durante la instalación es el primer administrador. Este perfil debe asignarse a las personas responsables de configurar la aplicación y gestionar los accesos.'),
        ('Usuario: trabajar con los permisos asignados', 'Es el perfil destinado al trabajo diario. El control de acceso por módulos, secciones y categorías está en integración para la próxima versión. Según el responsable del producto, el modelo de datos y las categorías ya están implementados. La asignación individual de permisos es el funcionamiento previsto; su aplicación completa todavía está pendiente de validación.'),
        ('Un ejemplo de reparto de funciones', 'La persona responsable de la implantación puede disponer de perfil Administrador para configurar la empresa y gestionar usuarios. Un empleado puede utilizar el perfil Usuario con acceso a las áreas comerciales que necesite. Este reparto mediante permisos individuales corresponde a la próxima versión y deberá verificarse en la auditoría de seguridad.'),
        ('Rol, estado y reglas de trabajo', 'Administrador o Usuario define el perfil de acceso; ACTIVO es el estado de habilitación. Ninguno de estos datos indica que la persona esté conectada en ese momento. Tener acceso a una operación tampoco elimina las validaciones de los documentos ni los requisitos del proceso comercial.'),
        ('Cómo se refleja en el listado', 'La columna Rol distingue Administrador y Usuario. En el menú de acciones, Seguridad de Usuario está deshabilitada para el administrador porque su acceso no se configura mediante permisos individuales. Para las cuentas de trabajo, este panel permite definir el acceso según las responsabilidades de cada persona.')]:
        result.extend([Paragraph(h,s['h3']),Paragraph(t,s['text'])]);md.extend(['**'+h+'**',t])
    result.append(PageBreak())
    result.extend([Paragraph(title,s['h2']),Paragraph(intro,s['text']),CaptureCard(out/'imagenes/usuarios-listado.png',caption='Usuarios del sistema · Vista inicial'),Spacer(1,12)])
    md.extend(['### '+title,intro,'![Usuarios del sistema](imagenes/usuarios-listado.png)'])
    for h,t in parts:
        result.extend([Paragraph(h,s['h3']),Paragraph(t,s['text'])]);md.extend(['**'+h+'**',t])
    h='Recorrido de la gestión de usuarios'
    t='El índice se amplía para separar el alta y los datos identificativos, la fotografía, el rol o grupo, el estado activo, la contraseña, la modificación, el historial de conexiones, los permisos, el borrado y las herramientas del listado. Cada procedimiento se desarrollará con sus pantallas y pruebas.'
    result.extend([Paragraph(h,s['h2']),Paragraph(t,s['text'])]);md.extend(['### '+h,t])
    for h,t in [
        ('Acciones del usuario', 'La estructura actual del frontend incluye Editar, Historial Conexiones, Borrar y Seguridad de Usuario. La acción Seguridad de Usuario aparece deshabilitada para las cuentas identificadas como administradoras. El alcance de los permisos y las restricciones se explicará al documentar ese panel.'),
        ('Herramientas del listado', 'El menú general incluye Refrescar datos y Exportar a Excel. Estas opciones actúan sobre el listado; sus resultados se documentarán durante las pruebas correspondientes.'),
        ('Siguientes pantallas', 'Continuaremos con el formulario Nuevo usuario y, después, los menús de acciones, el historial de conexiones y Seguridad de Usuario. La captura actual no acredita la creación, modificación ni eliminación de ninguna cuenta.')]:
        result.extend([Paragraph(h,s['h3']),Paragraph(t,s['text'])]);md.extend(['**'+h+'**',t])
    result.append(PageBreak())
    for name,title,before,after in [('usuario-alta-vacio', 'Nuevo usuario: datos de la cuenta', 'Pulsa Nuevo usuario desde el listado. Completa Fecha de Alta, Código de Usuario, Nombre Completo y Correo Electrónico. El botón junto al código permite generar un identificador. Selecciona Rol / Grupo, introduce la contraseña y revisa Usuario Activo antes de guardar.', 'La fotografía de perfil permite reconocer visualmente a la persona. Pulsa el icono de cámara situado junto al avatar para tomar una foto con la cámara del dispositivo. El navegador puede solicitar permiso para utilizarla. La fotografía complementa el nombre del usuario; no determina su rol ni sus permisos.'), ('usuario-selector-grupo', 'Seleccionar el rol o grupo', 'El selector presenta Administradores, Usuarios y Usuarios / TPVs. Elige el grupo que corresponda al uso de la cuenta. Administrador es el perfil de gestión; Usuario es el perfil habitual de trabajo. El comportamiento específico del grupo Usuarios / TPVs está pendiente de documentar.', 'Los permisos por módulos y categorías están en integración para la próxima versión. La presencia de estos grupos no acredita que todas las restricciones individuales estén ya aplicadas; su validación se realizará en la futura auditoría de seguridad.'), ('usuario-alta-relleno', 'Revisar el formulario y la fotografía de perfil', 'La captura muestra el alta rellenada, con el grupo Usuarios, la contraseña oculta y Usuario Activo marcado. Revisa la fecha, el código, el nombre y el correo antes de pulsar Guardar usuario. En este ejemplo todavía se muestra el avatar genérico: la fotografía aún no se ha tomado.', 'La foto guardada se utiliza como avatar en el listado de usuarios y para identificar visualmente al responsable en las vistas de tareas, incluido el calendario Gantt y las tareas del portal de clientes. Facilita reconocer a la persona asociada a una tarea. El botón Cambiar foto abre el diálogo Capturar Foto; toma la imagen y guarda el usuario para conservarla. El apartado Fotografía de perfil explica la autorización del navegador y la captura de la imagen.')]:
        result.extend([Paragraph(title,s['h2']),Paragraph(before,s['text']),CaptureCard(out/'imagenes'/(name+'.png'),440,title),Spacer(1,12),Paragraph(after,s['text']),PageBreak()])
        md.extend(['### '+title,before,'!['+title+'](imagenes/'+name+'.png)',after])
    for title,name,width,before,after in [
        ('Fotografía de perfil: permitir la cámara','usuario-permiso-camara',245,'Al pulsar el icono de cámara del formulario de usuario, el navegador puede pedir autorización para utilizarla. Para tomar la fotografía debes permitir el acceso a la cámara para el sitio de KiwiKERP. Este permiso lo gestiona el navegador; es independiente del rol del usuario.','El aviso de ejemplo permite seleccionar la cámara y elegir Permitir mientras visito el sitio o Permitir esta vez. Las opciones pueden variar según el navegador. Si deniegas el acceso, no podrás tomar la foto. Si lo bloqueaste anteriormente, revisa los permisos de cámara del sitio en el navegador y vuelve a abrir el diálogo. Comprueba que la cámara elegida es la que quieres utilizar.'),
        ('Tomar y guardar la fotografía','usuario-capturar-foto',320,'El diálogo Capturar Foto muestra la vista previa de la cámara. Una vez autorizado el acceso, espera a ver la imagen, encuadra tu rostro y pulsa Capturar Foto. La captura aportada muestra el área de vídeo negra; por sí sola no permite determinar el motivo.','La foto capturada se incorpora a la vista previa del perfil en el formulario de usuario. Pulsa Guardar usuario para conservarla. Puedes cerrar el diálogo con la X si no deseas capturar una imagen. Si no aparece vídeo, comprueba el permiso del navegador y la disponibilidad de la cámara antes de continuar. La imagen servirá para identificar visualmente al usuario en el listado y como responsable en las vistas de tareas.')]:
        result.extend([Paragraph(title,s['h2']),Paragraph(before,s['text']),CaptureCard(out/'imagenes'/(name+'.png'),width,title),Spacer(1,12),Paragraph(after,s['text']),PageBreak()])
        md.extend(['### '+title,before,'!['+title+'](imagenes/'+name+'.png)',after])
    title='Menú de opciones de un usuario'
    intro='Abre el menú de tres puntos de la columna Acciones en la fila del usuario. Antes de elegir una opción, comprueba el código y el nombre: las acciones corresponden a esa cuenta.'
    result.extend([Paragraph(title,s['h2']),Paragraph(intro,s['text']),CaptureCard(out/'imagenes/usuario-menu-acciones.png',250,'Opciones de la cuenta seleccionada'),Spacer(1,12)])
    md.extend(['### '+title,intro,'![Menú de opciones del usuario](imagenes/usuario-menu-acciones.png)'])
    for h,t in [
        ('Editar', 'Abre la ficha de la cuenta para revisar o modificar sus datos. Desde ella también puedes cambiar la fotografía y el estado Usuario Activo. Guarda los cambios para conservarlos.'),
        ('Historial Conexiones', 'Abre el historial de conexiones de la cuenta seleccionada. El apartado Historial de conexiones explica sus indicadores, gráfica y listado.'),
        ('Borrar', 'Inicia la acción de borrado de la cuenta seleccionada. No equivale a desactivarla. La confirmación se explica en el apartado de desactivación y borrado. Las posibles restricciones por datos relacionados quedan pendientes de comprobar.'),
        ('Seguridad de Usuario', 'Accede a la configuración individual de permisos. El control por módulos y categorías está en integración para la próxima versión, con el modelo de datos y las categorías implementados según el responsable del producto. Su funcionamiento completo queda pendiente de la futura auditoría de seguridad. Para administradores, esta opción aparece deshabilitada.')]:
        result.extend([Paragraph(h,s['h3']),Paragraph(t,s['text'])]);md.extend(['**'+h+'**',t])
    result.append(PageBreak())
    title='Historial de conexiones: análisis de actividad'
    intro='Selecciona Historial Conexiones en el menú de la cuenta. El título identifica al usuario consultado.'
    result.extend([Paragraph(title,s['h2']),Paragraph(intro,s['text']),CaptureCard(out/'imagenes/usuario-historial-conexiones.png',487,'Historial de conexiones del usuario'),Spacer(1,12)])
    md.extend(['### '+title,intro,'![Historial de conexiones](imagenes/usuario-historial-conexiones.png)'])
    for h,t in [
        ('Indicadores del historial', 'Total Registros muestra el número de conexiones registradas. Media diaria divide ese total entre los días distintos con conexiones: en el ejemplo, 6 registros en 2 días dan una media de 3,0. No incluye días sin conexiones. Última Actividad presenta la fecha y hora de la conexión más reciente mostrada; no indica que el usuario siga conectado.'),
        ('Tendencia de Conexiones', 'La gráfica agrupa por día las conexiones de la página cargada en el listado. En la captura hay 1 conexión el 26/09 y 5 el 25/09. Lee las fechas del eje horizontal: aquí aparecen de más reciente a más antigua, por lo que la línea ascendente no representa un crecimiento cronológico.'),
        ('Historial Reciente', 'Cada fila muestra la fecha y hora de una conexión. Fecha permite ordenar; el filtro selecciona un intervalo de fechas. Los controles inferiores permiten cambiar de página y elegir su tamaño.'),
        ('Cerrar la consulta', 'Pulsa Cerrar o la X para volver al listado. El historial registra accesos; no mide tiempo trabajado ni detalla las operaciones de cada sesión.')]:
        result.extend([Paragraph(h,s['h3']),Paragraph(t,s['text'])]);md.extend(['**'+h+'**',t])
    result.append(PageBreak())
    title='Desactivar una cuenta y confirmar su borrado'
    intro='Desactivar y borrar son acciones diferentes. Una cuenta desactivada permanece en el listado con estado INACTIVO. El borrado solicita eliminar la cuenta y muestra una confirmación expresa.'
    result.extend([Paragraph(title,s['h2']),Paragraph(intro,s['text']),CaptureCard(out/'imagenes/usuarios-inactivos.png',487,'Listado con cuentas activas e inactivas'),Spacer(1,12)])
    md.extend(['### '+title,intro,'![Usuarios inactivos](imagenes/usuarios-inactivos.png)'])
    for h,t in [
        ('Desactivar el acceso', 'Abre Editar en el menú de la cuenta, desmarca Usuario Activo y guarda. El listado muestra INACTIVO en rojo. La cuenta conserva su código, nombre y rol: desactivarla no la convierte en otro perfil. En la prueba realizada con QA_MANUAL_2509, un nuevo intento de inicio de sesión no permitió entrar al panel.'),
        ('Interpretar Última conexión', 'Una cuenta inactiva puede conservar una fecha de último acceso, como QA_MANUAL_2509, o mostrar Nunca, como Alberto Rodriguez en esta captura. El estado indica si la cuenta está habilitada; Última conexión informa de sus accesos registrados. No representa una sesión abierta.')]:
        result.extend([Paragraph(h,s['h3']),Paragraph(t,s['text'])]);md.extend(['**'+h+'**',t])
    result.extend([Paragraph('Confirmar la eliminación',s['h3']),CaptureCard(out/'imagenes/usuario-confirmacion-borrado.png',487,'Confirmación de borrado de la cuenta'),Spacer(1,12)])
    text='Selecciona Borrar en el menú de acciones. El diálogo identifica al usuario y advierte de que la acción no se puede deshacer. Comprueba el nombre antes de decidir. Cancelar permite abandonar la operación; Borrar confirma la solicitud de eliminación. Si solo necesitas impedir nuevos accesos conservando la cuenta, utiliza la desactivación. Esta captura muestra la confirmación, no el resultado del borrado; sus posibles restricciones por datos relacionados quedan pendientes de comprobar.'
    result.append(Paragraph(text,s['text']));md.extend(['**Confirmar la eliminación**','![Confirmación de borrado](imagenes/usuario-confirmacion-borrado.png)',text])
    result.append(PageBreak())
    h='Alta y estado del usuario: prueba realizada'
    t='Prueba realizada el 25/09/2026 en el entorno Cloud indicado por el responsable. Se creó la cuenta QA_MANUAL_2509, Prueba Manual Usuario, con grupo Usuarios y correo ficticio. La cuenta quedó inactiva al finalizar. No se modificaron las cuentas preexistentes ni se realizaron envíos de correo.'
    result.extend([Paragraph(h,s['h2']),Paragraph(t,s['text'])]);md.extend(['### '+h,t])
    for h,t in [
        ('Completar el alta', 'Pulsa Nuevo usuario. Introduce Fecha de Alta, Código de Usuario, Nombre Completo, Correo Electrónico, Rol / Grupo y Contraseña; revisa Usuario Activo y pulsa Guardar usuario. El botón junto al código genera un identificador que puede editarse antes de guardar. Al intentar guardar el formulario vacío se mostró: Campos incompletos. El código, nombre, email, rol y fecha de alta son obligatorios.'),
        ('Grupos disponibles en este entorno', 'El desplegable ofrece Administradores, Usuarios y Usuarios / TPVs. Los dos primeros son los perfiles del recorrido principal de este manual. El comportamiento específico de Usuarios / TPVs todavía no se ha probado.'),
        ('Resultado del alta y primer acceso', 'La cuenta apareció con rol Usuario, estado ACTIVO y última conexión Nunca. Permitió iniciar sesión con su código y contraseña. Al volver a entrar como administrador, la cuenta seguía en el listado y mostraba una fecha y hora de última conexión.'),
        ('Editar y desactivar', 'En Acciones, pulsa Editar. Código de Usuario y Fecha de Alta aparecen deshabilitados. Para desactivar, desmarca Usuario Activo y guarda. En la prueba se mostró Usuario guardado correctamente y el listado pasó a INACTIVO. Un nuevo intento de acceso con esa cuenta permaneció en el login; no se abrió el panel.'),
        ('Revisar los permisos iniciales', 'En esta prueba los seis módulos de Seguridad de Usuario aparecieron habilitados inicialmente: ENTITIES, PRODUCTS, SALES, REPORTING, TASKS y SYSTEM. No presupongas que una nueva cuenta carece de accesos: revisa su configuración. No se han validado todavía todas las secciones y acciones.')]:
        result.extend([Paragraph(h,s['h3']),Paragraph(t,s['text'])]);md.extend(['**'+h+'**',t])
    result.append(PageBreak())
    h='Estado de integración y observaciones de la prueba'
    result.append(Paragraph(h,s['h2']));md.append('### '+h)
    for h,t in [
        ('Acceso a Configuración pese a bloquear SYSTEM', 'Tras deshabilitar SYSTEM para la cuenta de prueba, el menú lateral dejó de mostrar Configuración. Sin embargo, el acceso reciente Configuración permitió abrir la pantalla y consultar datos de empresa y campos SMTP. No se intentó guardar cambios ni enviar correos. El responsable aclara que los permisos están en integración para la próxima versión, con el modelo de datos y las categorías implementados. Este resultado se conserva como referencia de una funcionalidad todavía incompleta. Se repetirá la misma prueba en la futura auditoría de seguridad; no se da por validada la restricción de acceso.'),
        ('Fecha de alta desplazada', 'Se seleccionó 25/09/2026 en el alta; al abrir Editar Usuario se mostró 24/09/2026. Se registra la diferencia observada, sin atribuir todavía una causa. Debe corregirse y comprobarse antes de dar por validado este campo.'),
        ('Recarga y continuidad de la sesión', 'Al recargar la página, la aplicación volvió al login. Se pudo continuar mediante un nuevo inicio de sesión. No se ha determinado si este comportamiento corresponde a la política prevista o a una incidencia.'),
        ('Alcance de la comprobación', 'Los resultados proceden de operaciones reales en el navegador y de nuevas lecturas tras iniciar sesión. No equivalen a una inspección directa de la base de datos ni a una prueba tras reiniciar el servidor. Quedan pendientes duplicados, fotografía, historial detallado, exportación, borrado, otros grupos y validación completa de permisos.')]:
        result.extend([Paragraph(h,s['h3']),Paragraph(t,s['text'])]);md.extend(['**'+h+'**',t])
    (out/'Gestion_usuarios.md').write_text('\n\n'.join(md),encoding='utf-8')
    result.append(PageBreak())
    return result
